-- Disposable role, lifecycle, rate and retry assertions; no fixture survives.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(1);
do $test$
declare
 admin uuid:=gen_random_uuid(); customer uuid:=gen_random_uuid(); worker uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid();
 r public.move_requests%rowtype; same public.move_requests%rowtype; e public.estimates%rowtype; j public.jobs%rowtype;
 truck public.trucks%rowtype; c public.conversations%rowtype; message public.messages%rowtype; retry uuid:=gen_random_uuid(); reservation uuid; newworker uuid:=gen_random_uuid();
 input jsonb:=jsonb_build_object('pickup','10 Test Lane','destination','20 Test Road','requestedDate',((now() at time zone 'America/Chicago')::date+10000)::text,'property','House','size','Studio','items','Boxes','access','Ground floor','notes','','pickupAddress',jsonb_build_object('street','10 Test Lane','city','Oxford','state','MS','zip','38655'),'destinationAddress',jsonb_build_object('street','20 Test Road','city','Tupelo','state','MS','zip','38801'));
 draft jsonb:='{"lines":[{"label":"Labor","amountCents":50000}],"inclusions":["Labor"],"exclusions":["Packing"],"terms":"Test"}';
begin
 insert into auth.users(id,email,raw_user_meta_data) select x,x::text||'@example.invalid','{"role":"admin","active":true}'::jsonb from unnest(array[admin,customer,worker,outsider]) x;
 if exists(select 1 from public.profiles where id=any(array[admin,customer,worker,outsider]) and role<>'customer') then raise exception 'Metadata selected a role';end if;
 update public.profiles set role='admin' where id=admin;
 update public.profiles set role='worker' where id=worker;
 insert into public.worker_availability(worker_id,day,available,start_time,end_time) select worker,d,true,'08:00','17:00' from generate_series(1,7) d;
 set local role authenticated;
 perform set_config('request.jwt.claims',json_build_object('sub',customer,'role','authenticated')::text,true);
 begin perform public.save_truck(null,'Forged',true);raise exception 'Customer managed truck';exception when insufficient_privilege then null;end;
 begin perform public.set_account_active(worker,false);raise exception 'Customer managed account';exception when insufficient_privilege then null;end;
 begin perform public.prepare_worker_invitation('no@example.invalid','Wrong');raise exception 'Customer invited worker';exception when insufficient_privilege then null;end;
 begin update public.profiles set active=false where id=customer;raise exception 'Customer edited active';exception when insufficient_privilege then null;end;
 input:=input||jsonb_build_object('_requestId',retry);
 r:=public.change_request(null,0,input);
 same:=public.change_request(null,0,input);
 if same.id<>r.id then raise exception 'Duplicate request created';end if;
 begin perform public.change_request(null,0,input||'{"notes":"Different"}');raise exception 'Retry payload mismatch accepted';exception when invalid_parameter_value then null;end;
 for n in 1..4 loop perform public.change_request(null,0,input||jsonb_build_object('_requestId',gen_random_uuid()));end loop;
 begin perform public.change_request(null,0,input||jsonb_build_object('_requestId',gen_random_uuid()));raise exception 'Request limit bypassed';exception when sqlstate 'P0001' then if sqlerrm<>'Request rate exceeded' then raise;end if;end;
 same:=public.change_request(null,0,input);if same.id<>r.id then raise exception 'Retry failed at quota';end if;
 c:=public.open_conversation('customer-support',customer);
 retry:=gen_random_uuid();message:=public.send_message(c.id,'First',retry);
 for n in 1..29 loop perform public.send_message(c.id,'Next',gen_random_uuid());end loop;
 same:=r;
 perform public.send_message(c.id,'First',retry);
 begin perform public.send_message(c.id,'Over quota',gen_random_uuid());raise exception 'Message limit bypassed';exception when sqlstate 'P0001' then if sqlerrm<>'Message rate exceeded' then raise;end if;end;
 perform set_config('request.jwt.claims',json_build_object('sub',admin,'role','authenticated')::text,true);
 begin perform public.set_account_active(admin,false);raise exception 'Self deactivation allowed';exception when invalid_parameter_value then null;end;
 perform public.set_account_active(outsider,false);
 perform set_config('request.jwt.claims',json_build_object('sub',outsider,'role','authenticated')::text,true);
 if exists(select 1 from public.profiles) or exists(select 1 from public.move_requests) then raise exception 'Inactive records readable';end if;
 begin perform public.open_conversation('customer-support',outsider);raise exception 'Inactive chat opened';exception when insufficient_privilege then null;end;
 begin perform public.change_request(null,0,input);raise exception 'Inactive request created';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',json_build_object('sub',admin,'role','authenticated')::text,true);
 perform public.set_account_active(outsider,true);
 truck:=public.save_truck(null,'Temporary truck',true);
 truck:=public.save_truck(truck.id,'Renamed truck',false);
 if truck.name<>'Renamed truck' or truck.active then raise exception 'Truck change failed';end if;
 truck:=public.save_truck(truck.id,truck.name,true);
 e:=public.save_estimate_draft(r.id,null,0,draft);e:=public.publish_reviewed_estimate(e.id,e.revision);
 perform set_config('request.jwt.claims',json_build_object('sub',customer,'role','authenticated')::text,true);
 e:=public.decide_estimate(e.id,'accepted');
 perform set_config('request.jwt.claims',json_build_object('sub',admin,'role','authenticated')::text,true);
 perform public.set_account_active(worker,false);
 begin perform public.save_job(e.id,(input->>'requestedDate')::date,'09:00','12:00','09:00','10:00',array[worker],truck.id);raise exception 'Inactive worker assigned';exception when invalid_parameter_value then null;end;
 perform public.set_account_active(worker,true);
 truck:=public.save_truck(truck.id,truck.name,false);
 begin perform public.save_job(e.id,(input->>'requestedDate')::date,'09:00','12:00','09:00','10:00',array[worker],truck.id);raise exception 'Inactive truck assigned';exception when invalid_parameter_value then null;end;
 truck:=public.save_truck(truck.id,truck.name,true);
 j:=public.save_job(e.id,(input->>'requestedDate')::date,'09:00','12:00','09:00','10:00',array[worker],truck.id);
 begin perform public.set_account_active(worker,false);raise exception 'Assigned worker deactivated';exception when invalid_parameter_value then null;end;
 begin perform public.set_account_active(customer,false);raise exception 'Active customer deactivated';exception when invalid_parameter_value then null;end;
 begin perform public.save_truck(truck.id,truck.name,false);raise exception 'Booked truck deactivated';exception when invalid_parameter_value then null;end;
 c:=public.open_conversation('move-team',j.id);
 j:=public.cancel_job(j.id,j.revision);
 perform public.set_account_active(worker,false);
 perform set_config('request.jwt.claims',json_build_object('sub',worker,'role','authenticated')::text,true);
 if exists(select 1 from public.jobs) or exists(select 1 from public.messages) or rebel_move_private.can_read_conversation(c.id) then raise exception 'Inactive worker retained access';end if;
 begin perform public.assigned_customer_phone(j.id);raise exception 'Inactive contact exposed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',json_build_object('sub',admin,'role','authenticated')::text,true);
 perform public.set_account_active(worker,true);
 reservation:=public.prepare_worker_invitation(newworker::text||'@example.invalid','Invited worker');
 reset role;
 insert into auth.users(id,email,invited_at,created_at,raw_user_meta_data) values(newworker,newworker::text||'@example.invalid',now(),now(),'{"role":"admin"}');
 if not exists(select 1 from public.profiles where id=newworker and role='customer' and not active) then raise exception 'Pending invitation not isolated';end if;
 set local role authenticated;
 perform set_config('request.jwt.claims',json_build_object('sub',admin,'role','authenticated')::text,true);
 perform public.complete_worker_invitation(reservation,newworker);
 reset role;
 if not exists(select 1 from public.profiles where id=newworker and role='worker' and active and full_name='Invited worker') then raise exception 'Trusted invitation failed';end if;
 if not exists(select 1 from rebel_move_private.worker_invitations where id=reservation and consumed_by=newworker) then raise exception 'Invitation not consumed';end if;
 set local role authenticated;
 perform set_config('request.jwt.claims',json_build_object('sub',admin,'role','authenticated')::text,true);
 begin perform public.prepare_worker_invitation(newworker::text||'@example.invalid','Other');raise exception 'Existing account reinvited';exception when invalid_parameter_value then null;end;
end $test$;
select pass('Active accounts, truck management, invite provenance, request retries and rate limits');
select * from finish();
rollback;
